const log = document.getElementById('log');

document.getElementById('borough-select').addEventListener('nys-change', (e) => {
  log.textContent = `Select changed: ${e.detail.value}`;
});

document.getElementById('borough-radiogroup').addEventListener('nys-change', (e) => {
  log.textContent = `Radio group changed: ${e.detail?.value ?? ''}`;
});

document.getElementById('landmarks-checkboxgroup').addEventListener('nys-change', () => {
  const checked = Array.from(document.querySelectorAll('nys-checkbox'))
    .filter((checkbox) => checkbox.checked)
    .map((checkbox) => checkbox.value);
  log.textContent = `Checkboxes changed: ${checked.join(', ') || '(none selected)'}`;
});

document.getElementById('notifications-toggle').addEventListener('nys-change', (e) => {
  log.textContent = `Toggle changed: ${e.detail.checked ? 'on' : 'off'}`;
});
